-- Q1: Join customers, orders and order items.

SELECT
    c.email,
    o.order_number,
    o.order_status,
    oi.product_name_snapshot,
    oi.quantity,
    oi.line_total
FROM customers c
         JOIN orders o
              ON o.customer_id = c.customer_id
         JOIN order_items oi
              ON oi.order_id = o.order_id
ORDER BY o.created_at DESC;


-- Q2: Revenue generated by each vendor.

SELECT
    v.business_name,
    SUM(oi.line_total) AS gross_item_revenue,
    COUNT(DISTINCT o.order_id) AS orders_count
FROM vendors v
         JOIN products p
              ON p.vendor_id = v.vendor_id
         JOIN order_items oi
              ON oi.product_id = p.product_id
         JOIN orders o
              ON o.order_id = oi.order_id
WHERE o.order_status IN (
                         'PAID', 'PROCESSING', 'SHIPPED', 'DELIVERED'
    )
GROUP BY v.vendor_id, v.business_name
ORDER BY gross_item_revenue DESC;


-- Q3: Common Table Expression for monthly sales.

WITH monthly_sales AS (
    SELECT
        DATE_TRUNC('month', created_at) AS sales_month,
        SUM(total_amount) AS revenue,
        COUNT(*) AS order_count
    FROM orders
    WHERE order_status <> 'CANCELLED'
    GROUP BY DATE_TRUNC('month', created_at)
)
SELECT
    sales_month,
    revenue,
    order_count,
    ROUND(
            revenue / NULLIF(order_count, 0),
            2
    ) AS average_order_value
FROM monthly_sales
ORDER BY sales_month;


-- Q4: Window function to rank products by sales
-- within each category.

SELECT
    c.category_name,
    p.product_name,
    SUM(oi.quantity) AS units_sold,
    DENSE_RANK() OVER (
        PARTITION BY c.category_id
        ORDER BY SUM(oi.quantity) DESC
    ) AS category_sales_rank
FROM categories c
         JOIN products p
              ON p.category_id = c.category_id
         JOIN order_items oi
              ON oi.product_id = p.product_id
GROUP BY
    c.category_id,
    c.category_name,
    p.product_id,
    p.product_name;


-- Q5: JSONB attribute search.

SELECT
    sku,
    product_name,
    attributes
FROM products
WHERE attributes @> '{"brand":"ExampleTech"}'::jsonb;


-- Q6: BASELINE execution plan.
-- Run this BEFORE creating the additional index.

EXPLAIN (ANALYZE, BUFFERS)
SELECT
    order_id,
    order_number,
    created_at,
    total_amount
FROM orders
WHERE order_status = 'PAID'
ORDER BY created_at DESC
    LIMIT 100;


-- Q7: Create the composite index.

CREATE INDEX IF NOT EXISTS idx_orders_status_created
    ON orders(order_status, created_at DESC);

ANALYZE orders;


-- Run the same query AFTER creating the index.

EXPLAIN (ANALYZE, BUFFERS)
SELECT
    order_id,
    order_number,
    created_at,
    total_amount
FROM orders
WHERE order_status = 'PAID'
ORDER BY created_at DESC
    LIMIT 100;


-- Q8: Inventory lookup plan.

EXPLAIN (ANALYZE, BUFFERS)
SELECT
    p.sku,
    p.product_name,
    i.quantity_on_hand
FROM products p
         JOIN inventory i
              USING(product_id)
WHERE p.sku = 'GAD-PHN-001';